        it = makeObject();
        it.add(addValue);
        // removed other assertion

        // add at start should be OK, added should not be next
        it = makeObject();
        it.add(addValue);
        // removed other assertion

        // add in middle and at end should be OK
        it = makeObject();
        while (it.hasNext()) {
            it.next();
            it.add(addValue);
            // check add OK
            assertEquals(addValue, it.previous());
}
