private void verifyNoMoreElements_1_oe() {
        assertTrue(!iterator.hasNext());
}

private void verifyNoMoreElements_2_oe() {
        // removed other assertion
        try {
            iterator.next();
            fail("NoSuchElementException expected");
}
}

private void verifyElementsInPredicate_1_oe(final String[] elements) {
        final Predicate<E> pred = new Predicate<E>() {
            @Override
            public boolean evaluate(final E x) {
                for (final String element : elements) {
                    if (element.equals(x)) {
                        return true;
                    }
                }
                return false;
            }
        };
        initIterator();
        iterator.setPredicate(pred);
        for (int i = 0; i < elements.length; i++) {
            final String s = (String)iterator.next();
            assertEquals(elements[i], s);
}
}

private void verifyElementsInPredicate_2_oe(final String[] elements) {
        final Predicate<E> pred = new Predicate<E>() {
            @Override
            public boolean evaluate(final E x) {
                for (final String element : elements) {
                    if (element.equals(x)) {
                        return true;
                    }
                }
                return false;
            }
        };
        initIterator();
        iterator.setPredicate(pred);
        for (int i = 0; i < elements.length; i++) {
            final String s = (String)iterator.next();
            // removed other assertion
            assertTrue(i == elements.length - 1 ? !iterator.hasNext() : iterator.hasNext());
}
}

private void verifyElementsInPredicate_3_oe(final String[] elements) {
        final Predicate<E> pred = new Predicate<E>() {
            @Override
            public boolean evaluate(final E x) {
                for (final String element : elements) {
                    if (element.equals(x)) {
                        return true;
                    }
                }
                return false;
            }
        };
        initIterator();
        iterator.setPredicate(pred);
        for (int i = 0; i < elements.length; i++) {
            final String s = (String)iterator.next();
            // removed other assertion
            // removed other assertion
        }
        verifyNoMoreElements();

        // test removal
        initIterator();
        iterator.setPredicate(pred);
        if (iterator.hasNext()) {
            final Object last = iterator.next();
            iterator.remove();
            assertTrue("Base of FilterIterator still contains removed element.", !list.contains(last));
}
}

