        }
        a = (Object[]) Array.newInstance(cl, 0);
        array = getCollection().toArray(a);
        // removed other assertion
        assertEquals("type-specific toArrays should be equal",Arrays.asList(array),Arrays.asList(getCollection().toArray()));
}

