public void testListAddByIndexBoundsChecking_1_oe() {
        if (!isAddSupported()) {
            return;
        }

        List<E> list;
        final E element = getOtherElements()[0];

        try {
            list = makeObject();
            list.add(Integer.MIN_VALUE, element);
            fail("List.add should throw IndexOutOfBoundsException [Integer.MIN_VALUE]");
}
}

